"""
Chunked mel extraction for faster-whisper.

faster_whisper.FeatureExtractor.__call__ builds a full-file STFT buffer of shape
(1, n_frames, n_fft//2+1) as complex128. For ~4h audio that is ~4.4 GiB and
raises MemoryError right as transcription starts (~20% UI progress).

This patch computes the same log-mel spectrogram in frame batches so peak RAM
stays bounded, then applies the global dynamic-range normalize once.
"""

from __future__ import annotations

from typing import Any

# ~82s of audio at hop=160; keeps complex STFT peak well under ~100MB.
_MAX_STFT_FRAMES = 8192
_PATCHED_ATTR = "_transub_chunked_mel"


def _log_mel_from_waveform(fe: Any, waveform: Any, *, padding: int = 160) -> Any:
    import numpy as np

    if waveform.dtype is not np.float32:
        waveform = waveform.astype(np.float32)
    if padding:
        waveform = np.pad(waveform, (0, padding))

    window = np.hanning(fe.n_fft + 1)[:-1].astype(np.float32)
    n_fft = int(fe.n_fft)
    hop = int(fe.hop_length)
    pad_amount = n_fft // 2

    # Match FeatureExtractor.stft center=reflect padding (batch dim kept).
    x = np.pad(waveform[None, :], ((0, 0), (pad_amount, pad_amount)), mode="reflect")
    batch, length = x.shape
    n_frames = 1 + (length - n_fft) // hop
    if n_frames <= 0:
        return np.zeros((fe.mel_filters.shape[0], 0), dtype=np.float32)

    frames = np.lib.stride_tricks.as_strided(
        x,
        (batch, n_frames, n_fft),
        (
            x.strides[0],
            hop * x.strides[1],
            x.strides[1],
        ),
    )
    # Original drops the last STFT frame via stft[..., :-1] (time axis).
    n_keep = max(0, n_frames - 1)
    mel_parts: list[Any] = []
    for start in range(0, n_keep, _MAX_STFT_FRAMES):
        end = min(n_keep, start + _MAX_STFT_FRAMES)
        sl = np.array(frames[:, start:end, :], dtype=np.float32, copy=True)
        sl *= window
        # rfft → (batch, time, freq); transpose to (freq, time) like upstream.
        spec = np.fft.rfft(sl, n=n_fft, axis=-1)
        del sl
        spec = spec.transpose(0, 2, 1)[0]
        magnitudes = np.abs(spec) ** 2
        del spec
        mel_parts.append(fe.mel_filters @ magnitudes)
        del magnitudes

    mel_spec = np.concatenate(mel_parts, axis=-1) if mel_parts else np.zeros(
        (fe.mel_filters.shape[0], 0), dtype=np.float32
    )
    del mel_parts
    log_spec = np.log10(np.clip(mel_spec, a_min=1e-10, a_max=None))
    del mel_spec
    log_spec = np.maximum(log_spec, log_spec.max() - 8.0)
    log_spec = (log_spec + 4.0) / 4.0
    return log_spec.astype(np.float32, copy=False)


def install_chunked_mel_patch() -> bool:
    """
    Monkey-patch faster_whisper.FeatureExtractor.__call__ for long-media safety.

    Idempotent. Returns True when the patch is active.
    """
    try:
        from faster_whisper.feature_extractor import FeatureExtractor
    except Exception:
        return False

    if getattr(FeatureExtractor.__call__, _PATCHED_ATTR, False):
        return True

    def chunked_call(self: Any, waveform: Any, padding: int = 160, chunk_length: Any = None):
        if chunk_length is not None:
            self.n_samples = int(chunk_length) * self.sampling_rate
            self.nb_max_frames = self.n_samples // self.hop_length
        return _log_mel_from_waveform(self, waveform, padding=int(padding or 0))

    setattr(chunked_call, _PATCHED_ATTR, True)
    FeatureExtractor.__call__ = chunked_call  # type: ignore[method-assign]
    return True
